package cache

import (
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
)

// TempPruneReport summarizes a temp-file sweep.
type TempPruneReport struct {
	Filesystem int   // # of orphan temp files removed
	BytesFreed int64 // total bytes reclaimed
	Errors     int   // # of files that failed to delete (logged, not fatal)
}

// PruneOrphanTemps walks cacheDir and removes leftover download temp files.
//
// Roxxy writes downloads to a temp file and atomically renames to the final
// path on completion. If the daemon crashes / is killed / loses network
// mid-download, the rename never happens and the temp file lingers forever.
// The contents are useless as-is (incomplete bytes, no metadata, no digest
// verification), so we delete rather than try to resume.
//
// Naming patterns swept (all generated by os.CreateTemp under cacheDir):
//
//   - ".tmp-*" prefix:   docker-blobs/sha256/aa/bb/.tmp-1234567890
//     archive mirror state files
//     util/stream.go fallback cache files
//   - "*.tmp" suffix:    cache/tmp/stream-1234567890.tmp
//     cache/tmp/put-1234567890.tmp
//     cacheDir/assemble-1234567890.tmp
//     .metadata-1234567890.tmp next to URL caches
//
// Called from `docker prune-blobs` — an operator-invoked maintenance op
// (not startup; roxxy daemons routinely run for weeks and would otherwise
// never clear these). Live downloads writing temp files when prune runs
// will fail their final rename and surface that as a transient cache
// miss; that's the operator's call to make when timing prune.
func PruneOrphanTemps(cacheDir string) (TempPruneReport, error) {
	var rep TempPruneReport
	if cacheDir == "" {
		return rep, fmt.Errorf("cacheDir empty")
	}
	err := filepath.WalkDir(cacheDir, func(path string, d fs.DirEntry, werr error) error {
		if werr != nil {
			// Skip unreadable entries; logging would be noisy for a startup
			// sweep across thousands of subdirs.
			if d != nil && d.IsDir() {
				return nil
			}
			return nil
		}
		if d.IsDir() {
			return nil
		}
		name := d.Name()
		if !isTempName(name) {
			return nil
		}
		info, statErr := d.Info()
		if statErr != nil {
			return nil
		}
		if rmErr := os.Remove(path); rmErr != nil {
			if !os.IsNotExist(rmErr) {
				rep.Errors++
			}
			return nil
		}
		rep.Filesystem++
		rep.BytesFreed += info.Size()
		return nil
	})
	if err != nil && !os.IsNotExist(err) {
		return rep, err
	}
	return rep, nil
}

// isTempName tests whether a filename matches a roxxy-generated temp pattern.
// Specifically: prefix ".tmp-" or exact extension ".tmp". The latter check is
// extension-only so it doesn't catch ".tmpl" template files.
func isTempName(name string) bool {
	if strings.HasPrefix(name, ".tmp-") {
		return true
	}
	if filepath.Ext(name) == ".tmp" {
		return true
	}
	return false
}
